<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import type {Point} from './model.ts';
export interface Place {id:string;name:string;point:Point;confidence:string;url:string;review?:boolean;aliases?:string[]}
const emit=defineEmits<{close:[];visit:[place:Place]}>(),query=ref(''),places=ref<Place[]>([]),error=ref(''),loading=ref(true);
async function load(){loading.value=true;error.value='';try{const r=await fetch('/places10b.json');if(!r.ok)throw Error('Places are unavailable. Please retry.');places.value=(await r.json()).places;}catch(e){error.value=String(e);}finally{loading.value=false;}}
onMounted(load);
const filtered=computed(()=>places.value.filter((p,i,a)=>[p.name,...(p.aliases??[])].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())&&a.findIndex(x=>x.name===p.name)===i));
</script>
<template><section class="locations-panel" aria-label="Wukari locations"><header><div><small class="eyebrow">AROUND WUKARI</small><h2>Find a place</h2></div><button class="close" aria-label="Close locations" @click="emit('close')">&times;</button></header><p>Explore the town or open the university map.</p><input v-model="query" aria-label="Search source-backed locations" placeholder="Search Wukari, FUW or a road&hellip;"/><p v-if="loading" role="status">Loading places&hellip;</p><p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="!loading&&!error&&!filtered.length">No matching places yet. Try Wukari or FUW.</p><article v-for="p in filtered" :key="p.id"><span class="badge">{{p.review?'CAMPUS REVIEW':'MAPPED LOCATION'}}</span><h3>{{p.name}}</h3><small>{{p.confidence}}</small><div><button @click="emit('visit',p)">{{p.review?'Open campus overview':'View on map'}}</button><a :href="p.url" target="_blank" rel="noreferrer">{{p.review?'Data & evidence':'Map source'}} &nearr;</a></div></article><p class="disclosure">Virtual exploration. Real-world access is unverified. Source details and map limitations are in Map Information.</p></section></template>
<style scoped>.locations-panel{position:absolute;z-index:8;inset:16px 16px 45px auto;width:min(430px,calc(100% - 32px));overflow:auto;background:#fafbf3;border:1px solid #bbcab4;border-radius:18px;padding:24px;box-shadow:0 8px 35px #243f3733}.locations-panel header{display:flex;justify-content:space-between;align-items:center}.locations-panel h2{margin:8px 0;font-size:24px}.eyebrow,.badge{font-size:9px;letter-spacing:1.1px;color:#637a62}.locations-panel p,.locations-panel small{font-size:12px;line-height:1.65;color:#526957}.locations-panel input{width:100%;padding:14px;border:1px solid #b2c3a9;border-radius:9px;font:inherit;font-size:12px;margin:5px 0}.locations-panel article{border-bottom:1px solid #d1dbc9;padding:20px 0}.badge{display:inline-block;background:#e5eedb;padding:5px 8px;border-radius:20px;font-weight:600}.locations-panel h3{font-size:16px;margin:10px 0 6px}.locations-panel button{min-height:44px;padding:10px 14px;border:1px solid #b2c3a9;border-radius:8px;background:#e2eadb;color:#214d3f}.locations-panel .close{border:0;background:transparent;font-size:25px}.locations-panel article div{display:flex;align-items:center;gap:18px;margin-top:14px;font-size:11px}.locations-panel article button{background:#215d4b;color:#fff;border-color:#215d4b}.disclosure{font-size:10px!important;margin-bottom:0}.locations-panel a{text-underline-offset:3px}</style>
